// Block (composition) — a newsletter subscription section with pending and error states.
// Stack owns arrangement; Form/TextField/Button/Alert own form behavior, controls, and feedback look.
import { useId } from "react";
import type { FormEvent, Ref } from "react";
import { Alert } from "../components/Alert";
import { Button } from "../components/Button";
import { Form } from "../components/Form";
import { Stack } from "../layouts/Stack";
import { TextField } from "../components/TextField";
import "./NewsletterSignup.css";

export interface NewsletterSignupProps {
  heading?: string;
  description?: string;
  onSubmit?: (email: string) => void;
  isPending?: boolean;
  errorMessage?: string;
  buttonLabel?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function NewsletterSignup({
  heading = "Subscribe",
  description,
  onSubmit,
  isPending,
  errorMessage,
  buttonLabel = "Subscribe",
  className,
  ref,
}: NewsletterSignupProps) {
  const headingId = useId();

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubmit?.(String(data.get("email") ?? ""));
  };

  return (
    <section
      ref={ref}
      aria-labelledby={heading ? headingId : undefined}
      className={className ? `sd-newslettersignup ${className}` : "sd-newslettersignup"}
    >
      <Stack gap="small" className="sd-newslettersignup__content">
        {/* The name and its supporting line are ONE unit, so they group at a tighter rung than the
          section's own — otherwise the same gap separates the pair as separates it from everything
          else, and two things read as three (`PageHeader` is the reference). */}
        <>
          <Stack gap="x-small" className="sd-newslettersignup__header">
            {heading && (
              <h2 id={headingId} className="sd-newslettersignup__heading sd-type-title-medium">
                {heading}
              </h2>
            )}
            {description && (
              <p className="sd-newslettersignup__description sd-type-body-medium">{description}</p>
            )}
          </Stack>
        </>
        {/* live="assertive": see `AlertProps.live` — submit failure is the case that earns it. */}
        {errorMessage && (
          <Alert variant="error" live="assertive">
            {errorMessage}
          </Alert>
        )}
        <Form isPending={isPending} onSubmit={handleSubmit} className="sd-newslettersignup__form">
          <Stack
            direction={{ small: "column", medium: "row" }}
            align={{ small: "stretch", medium: "center" }}
            gap="small"
            className="sd-newslettersignup__fields"
          >
            <TextField
              className="sd-newslettersignup__field"
              name="email"
              type="email"
              aria-label="Email"
              placeholder="Email address"
              autoComplete="email"
              isRequired
            />
            <Button type="submit" variant="primary" isPending={isPending}>
              {buttonLabel}
            </Button>
          </Stack>
        </Form>
      </Stack>
    </section>
  );
}

.sd-newslettersignup {
  width: 100%;
}

.sd-newslettersignup__heading,
.sd-newslettersignup__description {
  margin: 0;
}

.sd-newslettersignup__description {
  color: var(--sd-color-text-muted);
}

.sd-newslettersignup__form,
.sd-newslettersignup__field {
  width: 100%;
}

.sd-newslettersignup__field {
  flex: 1;
  min-width: 0;
}
